export interface StatusResult {
  server: {
    version: string;
    channel: string;
    role: "owner" | "peer" | "handedOver" | "unavailable" | "failed" | "disabled";
    protocol: number;
    port: number;
  };
  files: {
    session: string;
    name: string;
    /**
     * The file key of figma.com links; null when Figma gives none (see note).
     */
    key: string | null;
    page: string;
    editorType: string;
    allowEdits: boolean;
    /**
     * Its tab is the one in front in Figma; a file behind other tabs answers slowly.
     */
    visible: boolean;
    active: boolean;
    pluginVersion: string;
  }[];
  probe: { ok: boolean; ms: number | null; error: string | null } | null;
  pairing: {
    code: string | null;
    expiresInSeconds: number | null;
    lockedForSeconds: number | null;
    waiting: number;
  } | null;
  hint: string | null;
  note?: string;
}

