export interface NodesFindResult {
  nodes: {
    id: string;
    name: string;
    type: string;
    box?: { x: number; y: number; width: number; height: number } | null;
    /**
     * The layer's ancestors below its page, outermost first, each by id, name and type.
     */
    path?: { id: string; name: string; type: string }[];
    /**
     * A text's characters, its first 200.
     */
    characters?: string;
    /**
     * The text has more than the 200 characters given.
     */
    cut?: true;
    /**
     * With properties: every component property's value on the instance, by name; variant properties too.
     */
    properties?: { [k: string]: string | boolean };
    /**
     * The layer or one of its ancestors is hidden: a viewer does not see it.
     */
    hidden?: true;
    /**
     * A text's font size in px, or its distinct sizes in text order when it mixes them.
     */
    fontSize?: number | number[];
    /**
     * An instance's component properties whose value differs from the component's default, by name: what this copy changes.
     */
    changed?: { [k: string]: string | boolean };
    /**
     * Within "file": the page the layer is on.
     */
    page?: { id: string; name: string };
  }[];
  more: boolean;
  /**
   * With variant: the values matched, as the filter was read.
   */
  variant?: { [k: string]: string };
  /**
   * With counts: the instances found, by component and variant, in the order first met. A variant no instance uses is not listed.
   */
  counts?: {
    /**
     * The component set's name, or a component's without variants.
     */
    component: string;
    /**
     * The variant as Figma names it.
     */
    variant?: string;
    count: number;
  }[];
  /**
   * The time ran out before every layer was counted: counts cover the layers reached. Search within less.
   */
  countsCut?: true;
  /**
   * Without within: the name of the current page, the one searched.
   */
  page?: string;
  /**
   * When nothing was found on the current page: how to search elsewhere.
   */
  hint?: string;
}

export interface OutlineResult {
  xml: string;
  /**
   * How many layers the XML lists.
   */
  nodes: number;
}

export interface DesignReadResult {
  /** The design XML, as design_read writes it. */
  xml: string;
  /** The JSON block beside the XML, in its order. */
  json: DesignReadJson;
  /** The XML's elements as data, to filter layers without parsing the XML. */
  tree: DesignElement | null;
  /** With screenshot: true, the image's handle: return it and execute shows the image. */
  image?: string;
}
/** design_read's JSON block, as the tool builds it (DesignReader, ReadJson and the tool's own fields). */
export interface DesignReadJson {
  /** The layer read. */
  node: string;
  /** Each variable and paint or effect style the read uses, by its token name, with its value as the XML writes it. */
  tokens: Record<string, string>;
  /** Each text style the texts name, as its font shorthand with its spacing and case. */
  textStyles: Record<string, string>;
  /** Each font family the texts use, with its weights in numeric order (italic said). */
  fonts: Record<string, string[]>;
  /** The files the XML's src names (only planned unless assetsDir wrote them), or a video, which has no file. */
  assets: {
    node: string;
    kind: "icon" | "image" | "video";
    format?: string;
    src?: string;
    scale?: number;
    imageHash?: string;
  }[];
  /** The designer's Dev Mode measurements, when there are any: each end as "<id> <side>", the px between them. */
  measurements?: {
    from: string;
    to: string;
    px?: number;
    text?: string;
  }[];
  /** What the code should know or fix, one per kind with a count and examples. */
  hints: string[];
  /** Ids of the layers the read cut, $children="N" or $truncated="true" on them: read each on its own. */
  truncated: string[];
  /** With repeats: each run read as its first, the fields its layers hold apart, and a row of values per layer. */
  repeats?: {
    template: string;
    layers: string[];
    fields: {
      layer: string;
      path?: string;
      attribute: string;
    }[];
    rows: (string | string[])[][];
  }[];
  /** false when the files are only planned: every src is a plan, and a hint says how to write them. */
  written?: false;
  /** With assetsDir: the layers whose asset was not written, and why. */
  assetErrors?: {
    node: string;
    message: string;
    kind?: "video";
  }[];
  /** With nearby: the screen the layer is on, the designer's notes around it nearest first, and how many more. */
  nearby?: {
    screen: {
      id: string;
      name: string;
    };
    notes: {
      id: string;
      name: string;
      text: string;
      side: "over" | "left" | "right" | "above" | "below";
      distance: number;
    }[];
    more: number;
  };
}
/** One element of the XML: its layer's id, its tag, its attributes (CSS, and metadata such as name), a Text's text. */
export interface DesignElement {
  id: string;
  tag: string;
  attributes: Record<string, string>;
  text?: string;
  children: DesignElement[];
}

export interface ImageCompareResult {
  size: { node: string; reference: string };
  scale: number;
  /**
   * Root mean square colour difference, 0 to 255, both images over white.
   */
  rmse: number;
  /**
   * The share of pixels that differ by more than antialiasing does, 0 to 1.
   */
  different: number;
  /**
   * The box around every differing pixel, in px of the render; null when none differs.
   */
  box: { x: number; y: number; width: number; height: number } | null;
  /**
   * Horizontal edges by y: matched, shifted (by: + is lower in the render), missing, extra.
   */
  rows: {
    matched: number;
    shifted: { reference: number; node: number; by: number }[];
    missing: number[];
    extra: number[];
  };
  /**
   * Vertical edges by x: matched, shifted (by: + is further right in the render).
   */
  columns: {
    matched: number;
    shifted: { reference: number; node: number; by: number }[];
    missing: number[];
    extra: number[];
  };
  diff?: string;
  note?: string;
}

export interface StylesCompareResult {
  /**
   * Each pair's layer: what matched, what differs, what the build left out, what cannot be compared.
   */
  layers: {
    /**
     * Properties the build has as the design sets them.
     */
    matched: number;
    /**
     * Properties the build has otherwise, in the design's order.
     */
    mismatches: {
      property: string;
      /**
       * The design's value, its tokens' values in.
       */
      design: string;
      /**
       * What the design takes it from: a token, var(--name), or a text style, textStyle="Name".
       */
      from?: string;
      /**
       * The build's computed value.
       */
      build: string;
    }[];
    /**
     * Properties the design sets that the build's styles leave out: read them too and compare again.
     */
    notGiven: string[];
    /**
     * What the design writes in a way a computed style cannot be held against: an offset in percent or calc(), tracks in fr, a value in em without a font size.
     */
    notCompared: { property: string; design: string }[];
    node: string;
    name: string;
    /**
     * Its element in design_read: Frame, Text, Icon…
     */
    tag: string;
    label?: string;
  }[];
  /**
   * Layers the file does not hold.
   */
  missing: string[];
  /**
   * The build gave every property the design sets and each one matched (notCompared aside).
   */
  same: boolean;
  notes: string[];
}

export interface InspectResult {
  /**
   * What the boxes are measured from: a layer as `id "name"`, or the page.
   */
  relativeTo: string;
  /**
   * The point distance and angle are measured from, in the boxes' origin: the given one, or the centre of the given layer.
   */
  around?: { x: number; y: number };
  layers: {
    id: string;
    name: string;
    type: string;
    parent?: { id: string; name: string; type: string } | null;
    /**
     * The layout box.
     */
    box?: { x: number; y: number; width: number; height: number };
    /**
     * The box's centre, in the box's origin; for a turned layer its own centre too, as the box bounds the turned layer.
     */
    center?: { x: number; y: number };
    /**
     * The layer's ancestors below its page, outermost first, by id, name and type; the page it is on is in page.
     */
    path?: { id: string; name: string; type: string }[];
    /**
     * The page the layer is on, by id and name.
     */
    page?: { id: string; name: string };
    /**
     * With around: how far the layer's centre lies from that point, in px.
     */
    distance?: number;
    /**
     * With around: the direction of the layer's centre from that point, in degrees as CSS rotate() turns: 0 straight up, 90 right, 180 down, 270 left (clockwise, 0 to 360). Left out at the point itself.
     */
    angle?: number;
    /**
     * What is painted, when it differs from the box: centred or outside strokes, shadows, blur.
     */
    paintedBox?: { x: number; y: number; width: number; height: number };
    /**
     * Figma's rotation in degrees, counter-clockwise: CSS turns it as rotate(-rotation), as design_read writes.
     */
    rotation?: number;
    /**
     * Figma's blend mode, when it blends (SOFT_LIGHT, MULTIPLY): what design_read writes as mix-blend-mode.
     */
    blendMode?: string;
    /**
     * The blend mode as CSS's mix-blend-mode, when CSS has it.
     */
    mixBlendMode?: string;
    /**
     * How far the layer reaches past the room its parent gives it, in px.
     */
    overflow?: { left?: number; right?: number; top?: number; bottom?: number };
    strokes?: {
      align: string;
      weight?: number;
      weights?: { top: number; right: number; bottom: number; left: number };
      dashes?: number[];
      colors: string[];
      /**
       * The variables the stroke colours are bound to, by token, with their values; a colour without one is raw.
       */
      tokens?: { [k: string]: string };
      includedInLayout?: boolean;
    };
    /**
     * Every effect with Figma's own parameters.
     */
    effects?: {
      type: string;
      visible?: boolean;
      radius?: number;
      color?: { r: number; g: number; b: number; a?: number };
      offset?: { x: number; y: number };
      spread?: number;
      blendMode?: string;
      showShadowBehindNode?: boolean;
      boundVariables?: { [k: string]: unknown };
      blurType?: string;
      startRadius?: number;
      startOffset?: { x: number; y: number };
      endOffset?: { x: number; y: number };
      [k: string]: unknown;
    }[];
    text?: {
      /**
       * A text that mixes styles: each run with its character range, text, font family and style, size, decoration and fill (a token when it has one, else the colour). A text of one style has none.
       */
      segments?: {
        start: number;
        end: number;
        characters: string;
        fontFamily: string;
        fontStyle: string;
        fontSize: number;
        textDecoration: string;
        fill?: string;
      }[];
      lines: { text: string; break: ("line" | "paragraph") | null }[];
      lineHeights: string[];
      fontSizes: number[];
      autoResize: string;
      paragraphSpacing?: number;
    };
    /**
     * A layer's auto layout or grid as design_read's CSS names it, longhands in px: display, flex-direction, flex-wrap, padding-top/-right/-bottom/-left, gap or row-gap and column-gap, alignment; a bound side's token is in bound.
     */
    layout?: { [k: string]: number | string };
    /**
     * For a layer inside auto layout or a grid: its parent's layout as the layout field gives it (display, flex-direction, gap, padding…), so sizing in a flow reads in one answer.
     */
    parentLayout?: { [k: string]: number | string };
    fills?: {
      /**
       * The fill as a CSS value, top paint first: a colour, a gradient; a paint CSS cannot hold (a video) says so.
       */
      css: string;
      /**
       * The paint style it comes from, and the token design_read names it by.
       */
      style?: { name: string; token: string };
      /**
       * The variables the paints are bound to, by token, with their values.
       */
      tokens?: { [k: string]: string };
      /**
       * Every visible fill, top first: its type (SOLID, GRADIENT_LINEAR, IMAGE, VIDEO) and its blend mode.
       */
      paints: {
        type: string;
        /**
         * Figma's blend mode, when it blends (SOFT_LIGHT, MULTIPLY): what design_read writes as mix-blend-mode.
         */
        blendMode?: string;
        /**
         * The blend mode as CSS's mix-blend-mode, when CSS has it.
         */
        mixBlendMode?: string;
      }[];
    };
    /**
     * The variables bound to the layer's own fields (padding, gap, radius, size), by Figma field: the token design_read writes in var(), and its value.
     */
    bound?: { [k: string]: { token: string; value?: number | string | boolean } };
    interactions?: {
      trigger: string;
      summary: string;
      reaction: {
        trigger: { type: string; timeout?: number; delay?: number; [k: string]: unknown } | null;
        actions?: {
          type: string;
          destinationId?: string | null;
          destinationName?: string;
          navigation?: string;
          url?: string;
          openInNewTab?: boolean;
          transition?: {
            type: string;
            duration: number;
            direction?: string;
            easing: {
              type: string;
              easingFunctionCubicBezier?: { x1: number; y1: number; x2: number; y2: number };
              easingFunctionSpring?: { mass: number; stiffness: number; damping: number; [k: string]: unknown };
              [k: string]: unknown;
            };
            [k: string]: unknown;
          } | null;
          [k: string]: unknown;
        }[];
        [k: string]: unknown;
      };
    }[];
    component?: {
      name: string;
      set?: string;
      variant: { [k: string]: string };
      /**
       * Every component property by name (Figma's #id left out): its type, this instance's value and the component's default.
       */
      properties: { [k: string]: { type: string; value: string | boolean; default?: string | boolean } };
    };
  }[];
  /**
   * Ids that are not layers of this file.
   */
  missing: string[];
  /**
   * Layers asked for past the first 100, not read: inspect them next.
   */
  left?: number;
  /**
   * A subtree read listed more layers than the 100 read: the ids not read are in leftIds; inspect them next.
   */
  more?: true;
  /**
   * The ids of the layers a subtree read did not read, up to 500, as far as the scan reached.
   */
  leftIds?: string[];
}

export interface MeasureResult {
  /**
   * The layout boxes, or what is painted (strokes and shadows included).
   */
  measured: "box" | "painted";
  pairs: {
    a: { id: string; name: string };
    b: { id: string; name: string };
    summary: string;
    /**
     * The space between the two boxes on each axis, in px; negative where they overlap on that axis.
     */
    gap: { x: number; y: number };
    /**
     * B's edge minus A's, in px: 0 is aligned, positive is further right or lower.
     */
    edges: { left: number; right: number; top: number; bottom: number; centerX: number; centerY: number };
    /**
     * Which of the two holds the other within its box.
     */
    contains?: "a" | "b";
    /**
     * How far the inner box sits from each edge of the outer one.
     */
    inset?: { top: number; right: number; bottom: number; left: number };
  }[];
  /**
   * Ids that are not layers of this file.
   */
  missing: string[];
}

export interface NodesDiffResult {
  same: boolean;
  onlyInA: { path: string; id: string }[];
  onlyInB: { path: string; id: string }[];
  changed: {
    path: string;
    a: string;
    b: string;
    attributes: {
      /**
       * @minItems 2
       * @maxItems 2
       */
      [k: string]: never[];
    };
    /**
     * An icon's or image's own drawing differs: paths, colours, inner layers.
     */
    drawing?: true;
  }[];
  summary: string;
  /**
   * Differences past the ones listed: compare smaller parts of the two layers.
   */
  more?: number;
  /**
   * Set when the read stopped short of the layers' insides: below the cut nothing was compared.
   */
  cut?: string;
}

export interface BaselineSaveResult {
  name: string;
  /**
   * The baseline's file, absolute.
   */
  path: string;
  node: { id: string; name: string; type: string };
  file: { name: string; key: string | null };
  /**
   * Null from a plugin older than this server.
   */
  page: { id: string; name: string } | null;
  /**
   * When the design it keeps was read (the diff's read, with accept).
   */
  capturedAt: string;
  code: string[];
  /**
   * Layers read.
   */
  layers: number;
  /**
   * Variables and styles kept with their values in every mode.
   */
  tokens: number;
  /**
   * Branches the read did not hold whole: baseline_diff does not compare inside them.
   */
  cut: { id: string; name: string; children: number }[];
  /**
   * With replace: what the baseline it replaced kept, and how much the new read took in.
   */
  replaced?: {
    node: { id: string; name: string };
    capturedAt: string;
    counts: {
      changed: number;
      added: number;
      removed: number;
      moved: number;
      reordered: number;
      components: number;
      tokens: number;
    };
  };
  notes: string[];
}

export interface BaselineDiffResult {
  summary: string;
  baselines: {
    name: string;
    path: string;
    node?: { id: string; name: string; type: string };
    file?: { name: string; key: string | null };
    page?: { id: string; name: string } | null;
    capturedAt?: string;
    code?: string[];
    version?: { id: string | null; title: string; savedAt: string };
    status: "same" | "changed" | "missing" | "hidden" | "unavailable" | "unchecked";
    /**
     * Compared with another layer: node, or the root found again by name.
     */
    now?: { id: string; name: string };
    /**
     * Missing, hidden, unavailable: what happened, and what to do.
     */
    reason?: string;
    counts?: {
      changed: number;
      added: number;
      removed: number;
      moved: number;
      reordered: number;
      components: number;
      tokens: number;
    };
  }[];
  changes?: {
    changed: {
      path: string;
      id: string;
      was?: string;
      tag: string;
      attributes: {
        /**
         * @minItems 2
         * @maxItems 2
         */
        [k: string]: never[];
      };
      drawing?: true;
    }[];
    added: { path: string; id: string; tag: string; was?: "hidden"; xml?: string }[];
    removed: { path: string; id: string; tag: string; now?: "hidden" }[];
    moved: { path: string; id: string; from: string }[];
    reordered: { path: string; id: string; before: string[]; after: string[] }[];
    components: {
      component: string;
      path: string;
      change: "changed" | "added" | "removed";
      attributes?: {
        /**
         * @minItems 2
         * @maxItems 2
         */
        [k: string]: never[];
      };
      drawing?: true;
      xml?: string;
      instances: string[];
      of: number;
    }[];
    tokens: {
      token: string;
      name: string;
      was?: string;
      mode?: string;
      before: string | null;
      after: string | null;
      layers: number;
    }[];
    notCompared: { path: string; id: string; what: "children" | "drawing" }[];
  };
  /**
   * Pass it to baseline_save once your code has these changes.
   */
  accept?: string;
  /**
   * Baselines past 50, or entries past 200 in one list.
   */
  more?: number;
  notes: string[];
}

export interface BreakpointsFindResult {
  summary: string;
  /**
   * The screen at each width, narrowest first.
   */
  widths: {
    id: string;
    name: string;
    width: number;
    height: number;
    /**
     * How alike the two are, 0 to 1: names without size words, and shared children.
     */
    score: number;
    /**
     * The screen asked about.
     */
    this?: true;
  }[];
}

export interface FlowReadResult {
  page: string;
  starts: { id: string; name: string }[];
  screens: { id: string; name: string; width: number; height: number }[];
  links: {
    from: { id: string; name: string };
    layer: { id: string; name: string };
    trigger: string;
    action: string;
    to: { id: string; name: string } | null;
    url?: string;
    summary: string;
  }[];
  more: boolean;
}

export interface VariantsReadResult {
  set: { id: string; name: string };
  /**
   * Each variant property with its values.
   */
  properties: { [k: string]: string[] };
  /**
   * The default variant: the top-left one, as Figma takes it.
   */
  default: { id: string; name: string };
  variants: {
    id: string;
    name: string;
    props: { [k: string]: string };
    /**
     * The variant it is compared with: the one it differs from by a single property (a state first), else the default.
     */
    against: { id: string; name: string };
    /**
     * The CSS pseudo-class a state value suggests: :hover, :active, :focus-visible, :disabled.
     */
    pseudo?: string;
    same: boolean;
    /**
     * Attributes as [the default's, this variant's].
     */
    changed: {
      path: string;
      a: string;
      b: string;
      attributes: {
        /**
         * @minItems 2
         * @maxItems 2
         */
        [k: string]: never[];
      };
      /**
       * An icon's or image's own drawing differs: paths, colours, inner layers.
       */
      drawing?: true;
    }[];
    onlyInDefault: { path: string; id: string }[];
    onlyInVariant: { path: string; id: string }[];
  }[];
  /**
   * Variants left out: read a smaller set, or the variants one by one.
   */
  more?: number;
  /**
   * Set when the read of the set stopped short: below the cut the variants were not compared.
   */
  cut?: string;
}

export interface FontsCheckResult {
  summary: string;
  fonts: {
    family: string;
    /**
     * The weights used, "400 italic" for an italic.
     */
    weights: string[];
    /**
